-- Domain tables are intentionally outside the Data API exposed schema.
create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;
alter default privileges in schema public revoke execute on functions from public;
alter default privileges in schema app_private revoke execute on functions from public;
create table app_private.teams(id uuid primary key default gen_random_uuid(),name text not null check(length(btrim(name))>0 and octet_length(name)<=2048),normalized_name text unique not null,selectable boolean not null default true,version integer not null default 1);
create table app_private.categories(id uuid primary key default gen_random_uuid(),name text not null check(length(btrim(name))>0 and octet_length(name)<=2048),normalized_name text not null,kind text not null check(kind in ('PLACE','COURSE')),selectable boolean not null default true,version integer not null default 1,unique(kind,normalized_name),unique(id,kind));
create table app_private.browser_identities(id uuid primary key default gen_random_uuid(),token_hash text unique not null check(token_hash~'^[a-f0-9]{64}$'),expires_at timestamptz not null default now()+interval '180 days',last_seen_at timestamptz not null default now(),revoked_at timestamptz);
create table app_private.participants(id uuid primary key default gen_random_uuid(),identity_id uuid unique not null references app_private.browser_identities(id),nickname text not null check(length(btrim(nickname))>0 and octet_length(nickname)<=2048),team_id uuid not null references app_private.teams(id),version integer not null default 1);
create table app_private.targets(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('PLACE','COURSE')),name text not null check(length(btrim(name))>0 and octet_length(name)<=2048),provider text,place_id text,address text,lng double precision not null check(lng between -180 and 180),lat double precision not null check(lat between -90 and 90),route_json jsonb,approximate_length_m double precision,version integer not null default 1,unique(provider,place_id),unique(id,kind),check((kind='PLACE' and provider='kakao' and place_id is not null and route_json is null) or (kind='COURSE' and provider is null and place_id is null and address is null and route_json is not null)));
create table app_private.favorites(id uuid primary key default gen_random_uuid(),participant_id uuid not null references app_private.participants(id),target_id uuid not null,category_id uuid not null,kind text not null,message text not null check(length(btrim(message))>0 and octet_length(message)<=8192),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(participant_id,target_id),foreign key(target_id,kind) references app_private.targets(id,kind),foreign key(category_id,kind) references app_private.categories(id,kind));
create table app_private.photo_assets(id uuid primary key default gen_random_uuid(),owner_identity_id uuid not null references app_private.browser_identities(id),favorite_id uuid references app_private.favorites(id),slot integer check(slot between 1 and 3),state text not null default 'uploading' check(state in ('uploading','processing','ready','attached','deleting','deleted')),expires_at timestamptz not null default now()+interval '24 hours',lease_token uuid,lease_until timestamptz,final_object_key text,thumb_object_key text,unique(favorite_id,slot));
create table app_private.media_objects(object_key text primary key,asset_id uuid not null references app_private.photo_assets(id),variant text not null check(variant in ('raw','final','thumb')),attempt_id uuid not null,reserved_bytes bigint not null check(reserved_bytes>=0),actual_bytes bigint check(actual_bytes>=0),state text not null check(state in ('reserved','stored','delete_pending','deleted')),upload_expires_at timestamptz,writer_lease_until timestamptz,sha256 text check(sha256~'^[a-f0-9]{64}$'),created_at timestamptz not null default now(),released_at timestamptz,unique(asset_id,variant,attempt_id),check((state='deleted' and reserved_bytes=0 and released_at is not null) or (state<>'deleted' and released_at is null)));
alter table app_private.photo_assets add foreign key(final_object_key) references app_private.media_objects(object_key),add foreign key(thumb_object_key) references app_private.media_objects(object_key),add check(state not in ('ready','attached') or (final_object_key is not null and thumb_object_key is not null));
create table app_private.storage_budget(id smallint primary key check(id=1),limit_bytes bigint not null check(limit_bytes>0),updated_at timestamptz not null default now(),reconciled_at timestamptz,has_untracked_objects boolean not null default false);
insert into app_private.storage_budget(id,limit_bytes) values(1,734003200);
create table app_private.app_state(id smallint primary key check(id=1),revision bigint not null default 0,data_epoch uuid not null default gen_random_uuid(),updated_at timestamptz not null default now());
insert into app_private.app_state(id) values(1);
create table app_private.commands(actor_kind text not null,actor_id uuid not null,request_key uuid not null,payload_hash text not null,action text not null,resource_id uuid,outcome jsonb not null,revision bigint not null,created_at timestamptz not null default now(),primary key(actor_kind,actor_id,request_key));
create table app_private.registration_events(revision bigint primary key,favorite_id uuid references app_private.favorites(id) on delete set null,created_at timestamptz not null default now());
create table app_private.admin_users(auth_user_id uuid primary key,enabled boolean not null default true);
create table app_private.cleanup_jobs(object_key text primary key references app_private.media_objects(object_key),attempts integer not null default 0,next_attempt_at timestamptz not null default now(),lease_token uuid,lease_until timestamptz,completed_at timestamptz);
create table app_private.rate_counters(scope text not null,key_hash text not null,window_start bigint not null,count integer not null,expires_at timestamptz not null,primary key(scope,key_hash,window_start));
create table app_private.backup_runs(id uuid primary key default gen_random_uuid(),actor_auth_user_id uuid not null,request_key uuid not null,status text not null default 'running' check(status in ('running','succeeded','failed')),started_at timestamptz not null default now(),snapshot_at timestamptz,completed_at timestamptz,data_epoch uuid,migration_version text,object_count bigint check(object_count>=0),total_bytes bigint check(total_bytes>=0),manifest_sha256 text check(manifest_sha256~'^[a-f0-9]{64}$'),archive_sha256 text check(archive_sha256~'^[a-f0-9]{64}$'),lease_token uuid,lease_until timestamptz,error_code text,verification_source text not null default 'operator_reported' check(verification_source='operator_reported'),unique(actor_auth_user_id,request_key),check((status='running' and completed_at is null and lease_token is not null and lease_until is not null) or (status<>'running' and completed_at is not null and lease_token is null and lease_until is null)),check(status<>'succeeded' or (snapshot_at is not null and data_epoch is not null and migration_version is not null and object_count is not null and total_bytes is not null and manifest_sha256 is not null and archive_sha256 is not null)),check(status<>'failed' or error_code is not null));
create unique index backup_one_running on app_private.backup_runs((status)) where status='running';
create index on app_private.participants(team_id,id);
create index on app_private.favorites(target_id,created_at,id);
create index on app_private.favorites(category_id,target_id,participant_id);
create index on app_private.photo_assets(favorite_id);
create index on app_private.cleanup_jobs(next_attempt_at,lease_until) where completed_at is null;
do $$ declare r record; begin for r in select tablename from pg_tables where schemaname='app_private' loop execute format('alter table app_private.%I enable row level security',r.tablename); end loop; end $$;

create function app_private.fail(p_code text,p_detail jsonb default '{}'::jsonb) returns void language plpgsql set search_path='' as $$begin raise exception using errcode='P0001',message=p_code,detail=p_detail::text;end$$;
create function app_private.require_identity(p_actor uuid) returns void language plpgsql set search_path='' as $$begin if not exists(select 1 from app_private.browser_identities where id=p_actor and revoked_at is null and expires_at>now()) then perform app_private.fail('IDENTITY_EXPIRED');end if;end$$;
create function app_private.require_admin(p_actor uuid) returns void language plpgsql set search_path='' as $$begin if not exists(select 1 from app_private.admin_users where auth_user_id=p_actor and enabled) then perform app_private.fail('FORBIDDEN');end if;end$$;
create function app_private.bump() returns bigint language sql set search_path='' as $$update app_private.app_state set revision=revision+1,updated_at=now() where id=1 returning revision$$;
create function app_private.target_json(t app_private.targets) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',t.id,'kind',t.kind,'name',t.name,'address',t.address,'lng',t.lng,'lat',t.lat,'points',t.route_json->'coordinates','approximateLengthM',t.approximate_length_m,'version',t.version)$$;
create function app_private.favorite_json(f app_private.favorites) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('id',f.id,'targetId',f.target_id,'participantId',p.id,'nickname',p.nickname,'teamId',p.team_id,'teamName',t.name,'categoryId',f.category_id,'categoryName',c.name,'message',f.message,'version',f.version,'createdAt',f.created_at,'photos',coalesce((select jsonb_agg(jsonb_build_object('assetId',a.id,'slot',a.slot) order by a.slot) from app_private.photo_assets a where a.favorite_id=f.id and a.state='attached'),'[]'::jsonb)) from app_private.participants p join app_private.teams t on t.id=p.team_id join app_private.categories c on c.id=f.category_id where p.id=f.participant_id$$;
create function app_private.validate_points(p_points jsonb) returns void language plpgsql set search_path='' as $$declare v jsonb;begin if jsonb_typeof(p_points)<>'array' or jsonb_array_length(p_points) not between 2 and 200 or (select count(distinct value) from jsonb_array_elements(p_points))<2 then perform app_private.fail('VALIDATION_ERROR');end if; for v in select value from jsonb_array_elements(p_points) loop if jsonb_typeof(v)<>'array' or jsonb_array_length(v)<>2 or jsonb_typeof(v->0)<>'number' or jsonb_typeof(v->1)<>'number' or (v->>0)::double precision not between -180 and 180 or (v->>1)::double precision not between -90 and 90 then perform app_private.fail('VALIDATION_ERROR');end if;end loop;end$$;
create function app_private.route_length(p_points jsonb) returns double precision language sql immutable set search_path='' as $$with p as(select (value->>0)::double precision lng,(value->>1)::double precision lat,ordinality n from jsonb_array_elements(p_points) with ordinality),q as(select *,lag(lng) over(order by n) x,lag(lat) over(order by n) y from p) select coalesce(sum(6371000*2*asin(least(1,sqrt(power(sin(radians(lat-y)/2),2)+cos(radians(y))*cos(radians(lat))*power(sin(radians(lng-x)/2),2))))),0) from q where x is not null$$;

create function public.read_revision() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('revision',revision::text,'dataEpoch',data_epoch,'serverTime',now()) from app_private.app_state where id=1$$;
create function public.read_catalog() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('revision',s.revision::text,'dataEpoch',s.data_epoch,'allTeams',coalesce((select jsonb_agg(to_jsonb(t)-'normalized_name' order by t.name) from app_private.teams t),'[]'::jsonb),'selectableTeams',coalesce((select jsonb_agg(to_jsonb(t)-'normalized_name' order by t.name) from app_private.teams t where selectable),'[]'::jsonb),'allCategories',coalesce((select jsonb_agg(to_jsonb(c)-'normalized_name' order by c.name) from app_private.categories c),'[]'::jsonb),'selectableCategories',coalesce((select jsonb_agg(to_jsonb(c)-'normalized_name' order by c.name) from app_private.categories c where selectable),'[]'::jsonb)) from app_private.app_state s where id=1$$;
create function app_private.rankings(p_team uuid,p_category uuid) returns table(target_id uuid,kind text,name text,lng double precision,lat double precision,cnt bigint,rnk bigint) language sql stable set search_path='' as $$with counts as(select f.target_id,count(*) cnt from app_private.favorites f join app_private.participants p on p.id=f.participant_id where (p_team is null or p.team_id=p_team) and (p_category is null or f.category_id=p_category) group by f.target_id) select t.id,t.kind,t.name,t.lng,t.lat,c.cnt,rank() over(order by c.cnt desc) from counts c join app_private.targets t on t.id=c.target_id$$;
create function public.read_explore(p_team_id uuid default null,p_category_id uuid default null,p_rank_page integer default 1) returns jsonb language sql stable security definer set search_path='' as $$with r as(select * from app_private.rankings(p_team_id,p_category_id)),page as(select * from r order by cnt desc,target_id limit 20 offset (greatest(1,p_rank_page)-1)*20) select jsonb_build_object('revision',s.revision::text,'dataEpoch',s.data_epoch,'filters',jsonb_build_object('teamId',p_team_id,'categoryId',p_category_id),'pins',coalesce((select jsonb_agg(jsonb_build_object('targetId',target_id,'kind',kind,'lng',lng,'lat',lat,'count',cnt) order by target_id) from r),'[]'::jsonb),'rankingPage',coalesce((select jsonb_agg(jsonb_build_object('targetId',target_id,'kind',kind,'name',name,'count',cnt,'rank',rnk) order by cnt desc,target_id) from page),'[]'::jsonb),'hasMore',(select count(*) from r)>greatest(1,p_rank_page)*20) from app_private.app_state s where id=1$$;
create function public.read_target(p_target_id uuid,p_team_id uuid default null,p_category_id uuid default null,p_cursor text default null,p_expected_revision text default null) returns jsonb language sql stable security definer set search_path='' as $$with s as(select * from app_private.app_state where id=1),guard as(select case when not exists(select 1 from app_private.targets where id=p_target_id) then app_private.fail('TARGET_GONE') when p_expected_revision is not null and p_expected_revision<>(select revision::text from s) then app_private.fail('SNAPSHOT_CHANGED') else null end),filtered as(select f.* from app_private.favorites f join app_private.participants p on p.id=f.participant_id cross join guard where f.target_id=p_target_id and(p_team_id is null or p.team_id=p_team_id) and(p_category_id is null or f.category_id=p_category_id)),page as(select * from filtered where p_cursor is null or (created_at,id)<((split_part(p_cursor,'|',1))::timestamptz,(split_part(p_cursor,'|',2))::uuid) order by created_at desc,id desc limit 21),visible as(select * from page order by created_at desc,id desc limit 20) select jsonb_build_object('revision',s.revision::text,'dataEpoch',s.data_epoch,'target',app_private.target_json(t),'filteredCount',(select count(*) from filtered),'totalCount',(select count(*) from app_private.favorites where target_id=p_target_id),'favorites',coalesce((select jsonb_agg(app_private.favorite_json(f) order by f.created_at desc,f.id desc) from visible f),'[]'::jsonb),'nextCursor',case when(select count(*) from page)>20 then(select created_at::text||'|'||id::text from visible order by created_at,id limit 1) else null end) from s cross join guard cross join app_private.targets t where t.id=p_target_id$$;
create function public.read_booth(p_pin_category_id uuid default null) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('revision',s.revision::text,'dataEpoch',s.data_epoch,'pins',(public.read_explore(null,p_pin_category_id,1)->'pins'),'categoryRankings',coalesce((select jsonb_agg(jsonb_build_object('categoryId',c.id,'categoryName',c.name,'rankings',(select coalesce(jsonb_agg(jsonb_build_object('targetId',r.target_id,'kind',r.kind,'name',r.name,'count',r.cnt,'rank',r.rnk) order by r.cnt desc,r.target_id),'[]'::jsonb) from (select * from app_private.rankings(null,c.id) order by cnt desc,target_id limit 5) r)) order by c.name) from app_private.categories c),'[]'::jsonb)) from app_private.app_state s where s.id=1$$;
create function public.read_events(p_after_revision text,p_until_revision text,p_limit integer default 100) returns jsonb language sql stable security definer set search_path='' as $$with e as(select * from app_private.registration_events where revision>p_after_revision::bigint and revision<=p_until_revision::bigint order by revision limit least(100,greatest(1,p_limit))) select jsonb_build_object('rows',coalesce((select jsonb_agg(jsonb_build_object('revision',revision::text,'favoriteId',favorite_id) order by revision) from e),'[]'::jsonb),'nextCursor',case when(select count(*) from e)<least(100,greatest(1,p_limit)) then p_until_revision else (select max(revision)::text from e) end,'done',not exists(select 1 from app_private.registration_events where revision>coalesce((select max(revision) from e),p_after_revision::bigint) and revision<=p_until_revision::bigint))$$;
create function public.read_announcement(p_event_revision text) returns jsonb language sql stable security definer set search_path='' as $$select coalesce((select jsonb_build_object('skip',false,'favoriteId',f.id,'nickname',p.nickname,'teamName',tm.name,'targetName',t.name) from app_private.registration_events e join app_private.favorites f on f.id=e.favorite_id join app_private.participants p on p.id=f.participant_id join app_private.teams tm on tm.id=p.team_id join app_private.targets t on t.id=f.target_id where e.revision=p_event_revision::bigint),jsonb_build_object('skip',true))$$;

create function public.gateway_session(p_token_hash text) returns jsonb language plpgsql security definer set search_path='' as $$declare i app_private.browser_identities;begin insert into app_private.browser_identities(token_hash) values(p_token_hash) on conflict(token_hash) do nothing;select * into i from app_private.browser_identities where token_hash=p_token_hash for update;perform app_private.require_identity(i.id);if i.last_seen_at<now()-interval '1 day' then update app_private.browser_identities set expires_at=now()+interval '180 days',last_seen_at=now() where id=i.id returning * into i;end if;return jsonb_build_object('identityId',i.id,'expiresAt',i.expires_at,'hasProfile',exists(select 1 from app_private.participants where identity_id=i.id));end$$;
create function public.gateway_me(p_actor uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin perform app_private.require_identity(p_actor);select jsonb_build_object('id',p.id,'nickname',p.nickname,'teamId',p.team_id,'teamName',t.name,'version',p.version) into r from app_private.participants p join app_private.teams t on t.id=p.team_id where p.identity_id=p_actor;return r;end$$;
create function public.gateway_my_favorites(p_actor uuid,p_cursor text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin perform app_private.require_identity(p_actor);with page as(select f.* from app_private.favorites f join app_private.participants p on p.id=f.participant_id where p.identity_id=p_actor and(p_cursor is null or (f.created_at,f.id)<((split_part(p_cursor,'|',1))::timestamptz,(split_part(p_cursor,'|',2))::uuid)) order by f.created_at desc,f.id desc limit 21),v as(select * from page order by created_at desc,id desc limit 20) select jsonb_build_object('favorites',coalesce((select jsonb_agg(app_private.favorite_json(f)||jsonb_build_object('target',app_private.target_json(t)) order by f.created_at desc,f.id desc) from v f join app_private.targets t on t.id=f.target_id),'[]'::jsonb),'nextCursor',case when(select count(*) from page)>20 then(select created_at::text||'|'||id::text from v order by created_at,id limit 1) else null end) into r;return r;end$$;
create function app_private.replay(p_kind text,p_actor uuid,p_payload jsonb) returns jsonb language plpgsql set search_path='' as $$declare c app_private.commands;begin select * into c from app_private.commands where actor_kind=p_kind and actor_id=p_actor and request_key=(p_payload->>'requestKey')::uuid;if not found then return null;end if;if c.payload_hash<>p_payload->>'payloadHash' then perform app_private.fail('REQUEST_KEY_CONFLICT');end if;if c.action in ('create_favorite','edit_favorite') and not exists(select 1 from app_private.favorites where id=c.resource_id) then perform app_private.fail('RESULT_GONE');end if;return c.outcome||jsonb_build_object('replayed',true);end$$;
create function app_private.record(p_kind text,p_actor uuid,p_payload jsonb,p_action text,p_id uuid,p_target uuid default null) returns jsonb language plpgsql set search_path='' as $$declare r bigint;o jsonb;begin r:=app_private.bump();o:=jsonb_strip_nulls(jsonb_build_object('resourceId',p_id,'targetId',p_target,'revision',r::text,'replayed',false));insert into app_private.commands values(p_kind,p_actor,(p_payload->>'requestKey')::uuid,p_payload->>'payloadHash',p_action,p_id,o,r,now());return o;end$$;
create function app_private.detach(p_favorite uuid,p_keep jsonb default '[]') returns void language plpgsql set search_path='' as $$declare a record;begin for a in select id from app_private.photo_assets where favorite_id=p_favorite and not exists(select 1 from jsonb_array_elements(p_keep) v where (v->>'assetId')::uuid=photo_assets.id) order by id for update loop update app_private.photo_assets set favorite_id=null,slot=null,state='deleting' where id=a.id;update app_private.media_objects set state='delete_pending' where asset_id=a.id and state<>'deleted';insert into app_private.cleanup_jobs(object_key) select object_key from app_private.media_objects where asset_id=a.id and state='delete_pending' on conflict(object_key) do update set completed_at=null,next_attempt_at=now();end loop;end$$;
create function app_private.attach(p_actor uuid,p_favorite uuid,p_photos jsonb) returns void language plpgsql set search_path='' as $$declare v jsonb;a app_private.photo_assets;begin if jsonb_typeof(p_photos)<>'array' or jsonb_array_length(p_photos)>3 or(select count(distinct value->>'slot') from jsonb_array_elements(p_photos))<>jsonb_array_length(p_photos) or(select count(distinct value->>'assetId') from jsonb_array_elements(p_photos))<>jsonb_array_length(p_photos) then perform app_private.fail('VALIDATION_ERROR');end if;for v in select value from jsonb_array_elements(p_photos) order by value->>'assetId' loop select * into a from app_private.photo_assets where id=(v->>'assetId')::uuid for update;if not found or a.owner_identity_id<>p_actor or a.state not in('ready','attached') or(a.state='ready' and a.expires_at<=now()) or(a.favorite_id is not null and a.favorite_id<>p_favorite) or(v->>'slot')::int not between 1 and 3 then perform app_private.fail('PHOTO_GONE');end if;end loop;perform app_private.detach(p_favorite,p_photos);update app_private.photo_assets set slot=null where favorite_id=p_favorite;for v in select value from jsonb_array_elements(p_photos) loop update app_private.photo_assets set favorite_id=p_favorite,slot=(v->>'slot')::int,state='attached' where id=(v->>'assetId')::uuid;end loop;end$$;
create function public.gateway_create_favorite(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare p app_private.participants;t app_private.targets;c app_private.categories;f uuid:=gen_random_uuid();r jsonb;v jsonb:=p_payload->'target';begin perform app_private.require_identity(p_actor);perform 1 from app_private.app_state where id=1 for update;r:=app_private.replay('participant',p_actor,p_payload);if r is not null then return r;end if;select * into p from app_private.participants where identity_id=p_actor for update;if not found then if not exists(select 1 from app_private.teams where id=(p_payload#>>'{profile,teamId}')::uuid and selectable) then perform app_private.fail('VALIDATION_ERROR');end if;insert into app_private.participants(identity_id,nickname,team_id) values(p_actor,p_payload#>>'{profile,nickname}',(p_payload#>>'{profile,teamId}')::uuid) returning * into p;elsif p_payload?'profile' then perform app_private.fail('VALIDATION_ERROR');end if;
if v->>'type'='existing' then select * into t from app_private.targets where id=(v->>'targetId')::uuid for update;if not found then perform app_private.fail('TARGET_GONE');end if;
elsif v->>'type'='place' then insert into app_private.targets(kind,name,provider,place_id,address,lng,lat) values('PLACE',v->>'name','kakao',v->>'placeId',v->>'address',(v->>'lng')::double precision,(v->>'lat')::double precision) on conflict(provider,place_id) do update set provider=excluded.provider returning * into t;
elsif v->>'type'='course' then perform app_private.validate_points(v->'points');insert into app_private.targets(kind,name,lng,lat,route_json,approximate_length_m) values('COURSE',v->>'name',(v#>>'{points,0,0}')::double precision,(v#>>'{points,0,1}')::double precision,jsonb_build_object('type','LineString','coordinates',v->'points'),app_private.route_length(v->'points')) returning * into t;else perform app_private.fail('VALIDATION_ERROR');end if;
select * into c from app_private.categories where id=(p_payload->>'categoryId')::uuid;if not found or not c.selectable or c.kind<>t.kind then perform app_private.fail('VALIDATION_ERROR');end if;if exists(select 1 from app_private.favorites where participant_id=p.id and target_id=t.id) then perform app_private.fail('ALREADY_REGISTERED',jsonb_build_object('favoriteId',(select id from app_private.favorites where participant_id=p.id and target_id=t.id)));end if;insert into app_private.favorites(id,participant_id,target_id,category_id,kind,message) values(f,p.id,t.id,c.id,t.kind,p_payload->>'message');perform app_private.attach(p_actor,f,coalesce(p_payload->'photos','[]'));update app_private.targets set version=version+1 where id=t.id;r:=app_private.record('participant',p_actor,p_payload,'create_favorite',f,t.id);insert into app_private.registration_events(revision,favorite_id) values((r->>'revision')::bigint,f);return r;end$$;
create function public.gateway_edit_favorite(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare f app_private.favorites;c app_private.categories;r jsonb;begin perform app_private.require_identity(p_actor);perform 1 from app_private.app_state where id=1 for update;r:=app_private.replay('participant',p_actor,p_payload);if r is not null then return r;end if;select * into f from app_private.favorites where id=(p_payload->>'id')::uuid for update;if not found then perform app_private.fail('TARGET_GONE');end if;if not exists(select 1 from app_private.participants where id=f.participant_id and identity_id=p_actor) then perform app_private.fail('FORBIDDEN');end if;if f.version<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;select * into c from app_private.categories where id=(p_payload->>'categoryId')::uuid;if not found or c.kind<>f.kind or(not c.selectable and c.id<>f.category_id) then perform app_private.fail('VALIDATION_ERROR');end if;perform app_private.attach(p_actor,f.id,p_payload->'photos');update app_private.favorites set category_id=c.id,message=p_payload->>'message',version=version+1,updated_at=now() where id=f.id;update app_private.targets set version=version+1 where id=f.target_id;return app_private.record('participant',p_actor,p_payload,'edit_favorite',f.id,f.target_id);end$$;
create function public.gateway_delete_favorite(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare f app_private.favorites;r jsonb;begin perform app_private.require_identity(p_actor);perform 1 from app_private.app_state where id=1 for update;r:=app_private.replay('participant',p_actor,p_payload);if r is not null then return r;end if;select * into f from app_private.favorites where id=(p_payload->>'id')::uuid for update;if not found then perform app_private.fail('TARGET_GONE');end if;if not exists(select 1 from app_private.participants where id=f.participant_id and identity_id=p_actor) then perform app_private.fail('FORBIDDEN');end if;if f.version<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;perform app_private.detach(f.id);delete from app_private.favorites where id=f.id;update app_private.targets set version=version+1 where id=f.target_id;return app_private.record('participant',p_actor,p_payload,'delete_favorite',f.id,f.target_id);end$$;
create function public.gateway_edit_profile(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare p app_private.participants;r jsonb;begin perform app_private.require_identity(p_actor);perform 1 from app_private.app_state where id=1 for update;r:=app_private.replay('participant',p_actor,p_payload);if r is not null then return r;end if;select * into p from app_private.participants where identity_id=p_actor for update;if not found then perform app_private.fail('VALIDATION_ERROR');end if;if p.version<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;update app_private.participants set nickname=p_payload->>'nickname',version=version+1 where id=p.id;return app_private.record('participant',p_actor,p_payload,'edit_profile',p.id);end$$;
